function newGame(a){
  const o = gameOwner(a), opp = oppOf(o);
  const keys = [gameKey(a), 'wh-used-' + o.id].concat(opp && opp !== o ? ['wh-used-' + opp.id] : []);
  const was = keys.map(k => [k, store.get(k, null)]);
  store.set(keys[0], null); for(const k of keys.slice(1)) store.set(k, []);
  return () => { for(const [k, v] of was) store.set(k, v); };
}

function gcLasts(t){
  if(/\buntil the end of the battle(?! round)|\bfor the coming battle\b/i.test(t)) return 'battle';
  if(/\buntil the (?:end of the battle round|start of the next battle round)\b/i.test(t)) return 'round';
  if(/\buntil the start of your next command phase\b/i.test(t)) return 'command';
  if(/\bremains in that [a-z]+ until it enters a different one\b/i.test(t)) return 'kept';
  return '';
}

const gcWhen = x => {
  const t = String(x.text || '').replace(/\*\*/g, ''), at = ([...t.matchAll(GC_SEL)][0] || { index:0 }).index, s0 = t.lastIndexOf('.', at) + 1, sen = t.slice(s0).trim();
  const own = /^(?:if your army faction is [^,]+, )?((?:at the (?:start|end) of|in) [^,]+),/i.exec(sen);
  const any = /\b(at the (?:start|end) of (?:the |your |each |every )?[^,.]+|in your [a-z ]+? phase)/i.exec(t);
  const w = own ? own[1] : any ? any[1] : x.at || '';
  return w ? w.charAt(0).toUpperCase() + w.slice(1) : '';
};

function gcPick(c, g, side){
  const all = ((g.picks[side] || {})[c.key]) || {};
  if(c.lasts === 'command'){ const R = gcRound(c, g, side); return { v:all[R] || {}, since:R === String(g.round) ? null : +R, all }; }
  if(c.lasts !== 'kept') return { v:all[gcRound(c, g, side)] || {}, since:null, all };
  for(let r = g.round; r >= 1; r--) if(isObj(all[r]) && Object.keys(all[r]).length) return { v:all[r], since:r === g.round ? null : r, all };
  // none picked yet: the option the rule's words start the battle in ("At the start of the battle, … that unit enters Aegis Protocols")
  const m = /\b[Aa]t the start of the battle, [^.]*?\benters (?:the )?([A-Z][\w’']*(?: [A-Z][\w’']*)*)/.exec(String(c.rule.text || '').replace(/\*\*/g, ''));
  const gr = c.groups[0], o = m && gr.opts.find(x => m[1].toLowerCase().startsWith(x.name.toLowerCase()));
  return o ? { v:{ [gr.name]:o.name }, since:'start', all } : { v:{}, since:null, all };
}

function gPhaseHtml(L, g, ph, turn, picked, opts, pickOf){
  const firstTurn = g.half === 0, lastTurn = g.half === 1, start = ph === 'command' && firstTurn;
  const items = gamePhase(L, ph, turn, { start, round:g.round }), S = D.game.steps, st = S[ph];
  const groups = [];
  if(start && g.round === 1) groups.push(['Start of the battle', items.filter(e => e.step === 'battle')]);
  if(start) groups.push([gStepName(S.round[0]), items.filter(e => e.step === 'round' || e.step === 'first')]);
  groups.push([gStepName(st[0]), items.filter(e => e.step === 'start' || (e.step === 'turnStart' && ph === 'command'))]);
  if(ph === 'command' && opts.cp) groups.push([gStepName([D.game.cp[0].num, D.game.cp[0].title]), [], rt(D.game.cp[0].text)]);   // 08.02, after 08.01
  const during = items.filter(e => e.step === 'during' || (e.step === 'turnStart' && ph !== 'command') || (e.step === 'turnEnd' && ph !== 'fight') || (e.step === 'roundEnd' && !(ph === 'fight' && lastTurn)));
  // 08.03: a rule whose words name the Battle-shock step ("Battle-shock step of your Command phase"); 08.04's own words leave
  // out the rules "triggered … by battle-shock rolls"
  const mid = st.slice(1, -1), shock = ph === 'command' ? mid.find(([n]) => n === '08.03') : null;
  const inShock = e => !!shock && /\bbattle-shock step\b/i.test(e.kind === 'strat' ? e.s.when : String((e.ab || e.x || {}).text || '').replace(/\*\*/g, ''));
  if(shock) groups.push([gStepName(shock), during.filter(inShock)]);
  groups.push([mid.filter(x => x !== shock).map(gStepName).join(' · ') || 'During the phase', during.filter(e => !inShock(e))]);
  groups.push([gStepName(st[st.length - 1]), items.filter(e => e.step === 'end')]);
  if(ph === 'fight') groups.push(['End of the turn', items.filter(e => e.step === 'turnEnd')]);
  if(ph === 'fight' && lastTurn) groups.push([gStepName(S.round[1]), items.filter(e => e.step === 'roundEnd')]);
  const sort = list => list.slice().sort((x, y) => (x.kind === 'strat') - (y.kind === 'strat') || (x.kind === 'strat' && y.kind === 'strat' ? (y.usable - x.usable) : 0));
  let h = groups.filter(([, list, extra]) => list.length || extra).map(([title, list, extra]) => '<div class="gph"><p class="gpt">' + title + '</p>' + (extra || '') + gRows(L, sort(list), picked, pickOf) + '</div>').join('');
  const any = items.filter(e => e.any);
  if(any.length) h += '<details class="gx"' + (opts.fold && opts.fold.any ? ' open' : '') + ' data-gfold="any"><summary><span>Any phase</span><span class="c">' + any.length + '</span>' + chev + '</summary>' + gRows(L, sort(any), picked, pickOf) + '</details>';
  return h || '<p class="note">Nothing of this list is tagged for this phase.</p>';
}

function gRows(L, items, picked, pickOf){
  const own = L.id === cur.army;
  const now = e => { const n = pickOf ? pickOf(e) : ''; return n ? '<span class="gpn">Picked: ' + esc(n) + '</span>' : ''; };
  return items.map(e => {
    if(e.kind === 'strat'){ const s = e.s, pb = own && perBattle(s);
      return '<div class="gr gs' + (e.usable ? '' : ' none') + '"><span class="cp' + (s.cp >= 2 ? ' hot' : '') + '">' + esc(s.cp) + '<small>CP</small></span><span class="grb">' + gLink(L, 'strat', s.id, s.name) +
        (s.gist ? '<span class="sg">' + esc(s.gist) + '</span>' : '') + (e.usable ? '' : '<span class="from">' + esc(inArmy(L, () => usersLine(s))) + '</span>') + (pb ? ticks('s:' + s.id, pb.n, '', s.name) : '') + '</span></div>'; }
    if(e.kind === 'rule'){ const r = e.x, pb = own && perBattle(r, true) && !/per battle\b(?! round)[^.)]*\bper unit\b/i.test(r.text || '');
      // the Overview's boxes: "You can only select each of these abilities once per battle" (Kindred Sorcery) has one per ability
      const each = pb && /\beach of these [a-z ]+ once per battle/i.test(r.text) && r.table;
      const boxes = !pb ? '' : each ? r.table.map(o => ticks('r:' + r.name + ':' + o[0], 1, o[0], o[0])).join('') : ticks('r:' + r.name, pb.n, '', r.name);
      return '<div class="gr"><span class="grb">' + gLink(L, 'rule', e.name, e.name) + ' <span class="from">· ' + esc(e.src) + '</span>' + now(e) + (boxes ? '<span class="gtk">' + boxes + '</span>' : '') + '</span></div>'; }
    const p = picked ? picked(e.ab, e.units) : null, pb = own && perBattle(e.ab) && !naReason(e.ab);
    const who = e.ab.who && (p !== null || !e.src.includes(e.ab.who.replace(/: pick one$/, ''))) ? e.ab.who.replace(/: pick one$/, '') : '';
    const boxes = !pb ? '' : perBattle(e.ab).army ? abilityTicks(e.ab, e.units[0]) : e.units.flatMap(u => Array.from({ length:u.copies || 1 }, (_, i) =>
      ticks(copyKey(e.ab, u, i), perBattle(e.ab).n, e.units.length > 1 || (u.copies || 1) > 1 ? shortName(u) + ((u.copies || 1) > 1 ? ' ' + (i + 1) : '') : '', e.ab.name))).join('');
    return '<div class="gr' + (p === false ? ' none' : '') + '"><span class="grb">' + gLink(L, 'ability', e.key, e.ab.name) + ' <span class="from">· ' + esc(e.src) + '</span>' +
      (who ? ' <span class="tg m">' + esc(who) + (p === true ? ': picked' : p === false ? ': not picked' : '') + '</span>' : '') + now(e) + (boxes ? '<span class="gtk">' + boxes + '</span>' : '') + '</span></div>';
  }).join('');
}

function gChoiceHtml(c, g, side, opp){
  const P = gcPick(c, g, side), v = P.v, R = gcRound(c, g, side);
  const pick = (grp, opt) => esc(JSON.stringify([c.key, R, grp, opt || '']));
  const used = c.once && !c.unit ? new Set(c.groups.flatMap(gr => gr.opts.filter(o => usedSet().has('r:' + c.name + ':' + o.row + '#0')).map(o => o.name))) : new Set();
  const lasts = c.lasts === 'battle' ? 'For the battle' : c.lasts === 'kept' ? 'Until another is picked' : c.lasts === 'command' ? 'Until the start of your next Command phase' : 'Battle round ' + g.round;
  let h = '<div class="gc"><div class="gch">' + linkTo(c.link[0], c.link[1], c.name) + ' <span class="from">· ' + esc(c.src) + '</span></div>' +
    '<p class="gcw">' + esc(c.when) + (c.when ? ' · ' : '') + '<b>' + esc(lasts) + '</b>' + (P.since === 'start' ? ' <span class="from">(from the start of the battle)</span>' : P.since ? ' <span class="from">(picked in battle round ' + P.since + ')</span>' : '') + '</p>' +
    // a step the Event Companion's mission sequence (Before the battle) does not have, named as the rule names it
    ((m => m && !D.game.sequence.some(([, t]) => norm(t) === norm(m[1])) ? gNote('the Event Companion’s mission sequence (Before the battle, below) has no step called ' + esc(m[1]) + '.') : '')(/\bthe ([A-Z][a-z]+(?: [A-Z][a-z]+)+) step\b/.exec(c.when)));
  for(const gr of c.groups){
    const on = gcNames(v[gr.name]);
    h += '<div class="chips" role="group"' + (gr.name ? ' aria-label="' + esc(gr.name) + '"' : '') + '>' + (gr.name ? '<span class="gcg">' + esc(gr.name) + '</span>' : '') +
      gr.opts.map(o => { const sel = on.includes(o.name), u = !sel && used.has(o.name);
        return '<button class="chip' + (sel ? ' on' : '') + (u ? ' used' : '') + '" data-gpick="' + pick(gr.name, o.name) + '" aria-pressed="' + sel + '">' + esc(o.name) + (u ? '<span class="u">used</span>' : '') + '</button>'; }).join('') +
      (c.rolled ? '<button class="chip rl' + (v['rolled:' + gr.name] ? ' on' : '') + '" data-gpick="' + pick('rolled:' + gr.name) + '" aria-pressed="' + !!v['rolled:' + gr.name] + '">Rolled</button>' : '') + '</div>';
    for(const o of gr.opts.filter(o => on.includes(o.name))){
      h += '<div class="gq gpk"><span class="gqs">' + esc((gr.name ? gr.name + ' ' : '') + o.name + (o.title ? ' · ' + o.title : '')) + '</span>' + rt(o.text) + '</div>';
      const tg = gcTargets(o.text, opp);
      if(tg && tg.length){ const t = v['target:' + gr.name];
        h += '<div class="chips gtg" role="group" aria-label="Their unit"><span class="gcg">Their unit</span>' + tg.map(x => '<button class="chip' + (t === x.id ? ' on' : '') + '" data-gpick="' + pick('target:' + gr.name, x.id) + '" aria-pressed="' + (t === x.id) + '">' + esc(x.name) + '</button>').join('') + '</div>'; }
    }
  }
  if(c.state) h += '<div class="chips"><button class="chip' + (v['state'] ? ' on' : '') + '" data-gpick="' + pick('state') + '" aria-pressed="' + !!v['state'] + '">' + esc(c.state) + '</button></div>';
  // the picks of the other battle rounds of this game
  if(c.lasts !== 'battle'){
    const past = Object.keys(P.all).filter(r => r !== R && +r >= 1).sort((x, y) => x - y).map(r => [r, c.groups.flatMap(gr => gcNames((P.all[r] || {})[gr.name]))]).filter(([, n]) => n.length);
    if(past.length) h += '<p class="gcp">' + past.map(([r, n]) => 'Round ' + r + ': ' + esc(n.join(', '))).join(' · ') + '</p>';
  }
  return h + '</div>';
}
